      gap: 28px;
      padding: 28px;
      border: 1px solid rgba(217, 226, 240, 0.8);
      border-radius: var(--radius-lg);
      background: rgba(255, 255, 255, 0.92);
      box-shadow: var(--shadow);
      backdrop-filter: blur(12px);
    }

    .preview {
      margin: 0;
      overflow: hidden;
      border-radius: 20px;
      background: #e2e8f0;
      min-width: 0;
    }

