      line-height: 1.6;
    }

    .meta {
      display: grid;
      gap: 12px;
      padding: 18px;
      border: 1px solid var(--panel-border);
      border-radius: var(--radius-md);
      background: #f8fbff;
    }

    .meta strong {
      color: var(--text);
    }

    .actions {
      display: flex;
      flex-wrap: wrap;
      gap: 12px;
    }

    button {
      appearance: none;
      border: 0;
      border-radius: 999px;
      padding: 14px 20px;
      font: inherit;
      font-weight: 700;
      cursor: pointer;
      transition: transform 0.18s ease, background-color 0.18s ease, box-shadow 0.18s ease;
    }

    button:hover {
      transform: translateY(-1px);
    }

    button:focus-visible {
      outline: 3px solid #93c5fd;
      outline-offset: 3px;
    }

    .secondary {
      color: var(--text);
      background: #e8eef8;
    }

    .secondary:hover {
      background: #dce6f5;
    }

    .trigger,
    .danger {
      color: #fff;
      background: var(--danger);
      box-shadow: 0 12px 24px rgba(220, 38, 38, 0.24);
    }

    .trigger:hover,
    .danger:hover {
      background: var(--danger-strong);
    }

    .status {
      min-height: 1.5rem;
      margin: 0;
      font-weight: 600;
      color: var(--primary-strong);
    }

    dialog {
      width: min(100% - 32px, 440px);
      padding: 0;
      border: 0;
      border-radius: 22px;
      background: var(--panel);
      color: var(--text);
      box-shadow: 0 28px 80px rgba(15, 23, 42, 0.35);
    }

    dialog::backdrop {
      background: rgba(15, 23, 42, 0.55);
      backdrop-filter: blur(4px);
    }

    .dialog-content {
      padding: 28px;
    }

    .dialog-icon {
      width: 52px;
      height: 52px;
      display: grid;
      place-items: center;
      margin-bottom: 18px;
      border-radius: 16px;
      font-size: 1.4rem;
      background: #fee2e2;
      color: var(--danger);
    }

    h2 {
      margin: 0 0 12px;
      font-size: 1.5rem;
    }

    .dialog-copy {
      margin: 0;
      color: var(--muted);
      line-height: 1.6;
    }

    .dialog-actions {
      display: flex;
      justify-content: flex-end;
      flex-wrap: wrap;
      gap: 12px;
      margin-top: 24px;
    }

    @media (max-width: 760px) {
      .card {
        grid-template-columns: 1fr;
        padding: 20px;
      }

      .preview img {
        min-height: 280px;
      }

      .dialog-actions,
      .actions {
        flex-direction: column;
      }

      .dialog-actions button,
      .actions button {
        width: 100%;
      }
    }

    @media (forced-colors: active) {
      .card,
      .meta,
      dialog {
        border: 1px solid CanvasText;
      }

      button {
        border: 1px solid ButtonText;
      }
    }
  </style>
</head>
<body>
  <main class="page" id="main-content">
    <section class="card" aria-labelledby="page-title">
