        </p>

        <div class="meta" aria-label="Image metadata">
          <p><strong>Collection:</strong> Travel inspiration</p>
          <p><strong>Uploaded:</strong> May 4, 2026</p>
          <p><strong>Resolution:</strong> 6240 x 4160</p>
        </div>

        <div class="actions">
          <button type="button" class="secondary">Download</button>
          <button type="button" class="trigger">Delete image</button>
        </div>

        <p class="status" id="status-message" aria-live="polite"></p>
      </div>
    </section>
  </main>

  <dialog id="delete-dialog" aria-labelledby="dialog-title" aria-describedby="dialog-description">
    <div class="dialog-content">
      <div class="dialog-icon" aria-hidden="true">!</div>
      <h2 id="dialog-title">Delete this image?</h2>
      <p class="dialog-copy" id="dialog-description">
        This will remove <strong>Alpine Evening</strong> from your library. This action cannot be undone.
      </p>

      <div class="dialog-actions">
        <button type="button" class="secondary" id="cancel-button">Cancel</button>
        <button type="button" class="danger" id="confirm-button">Delete image</button>
      </div>
    </div>
  </dialog>

  <script>
    const trigger = document.querySelector(".trigger");
    const dialog = document.getElementById("delete-dialog");
