 <body>
   <a class="skip-link" href="#main-content">Skip to main content</a>
   <main class="page" id="main-content">
     <section class="card" aria-labelledby="page-title">
       <figure class="preview">
         <img
           src="https://images.unsplash.com/photo-1519608487953-e999c86e7455?auto=format&fit=crop&w=1200&q=80"
           alt="Snow-covered mountain peaks reflected in a calm alpine lake at sunset"
         >
       </figure>

       <div class="details">
         <p class="eyebrow">Image details</p>
         <h1 id="page-title">Alpine Evening</h1>
         <p class="description">
           A full-resolution preview of your selected image, ready to review before you keep,
           share, or remove it from your library.
         </p>

         <div class="meta" aria-label="Image metadata">
           <p><strong>Collection:</strong> Travel inspiration</p>
           <p><strong>Uploaded:</strong> May 4, 2026</p>
           <p><strong>Resolution:</strong> 6240 x 4160</p>
         </div>

         <div class="actions">
           <button type="button" class="secondary">Download</button>
           <button type="button" class="trigger">Delete image</button>
         </div>

         <p class="status" id="status-message" aria-live="polite"></p>
       </div>
     </section>
   </main>

   <dialog id="delete-dialog" aria-labelledby="dialog-title" aria-describedby="dialog-description">
     <div class="dialog-content">
       <div class="dialog-icon" aria-hidden="true">!</div>
       <h2 id="dialog-title">Delete this image?</h2>
       <p class="dialog-copy" id="dialog-description">
         This will remove <strong>Alpine Evening</strong> from your library. This action cannot be undone.
       </p>

       <div class="dialog-actions">
         <button type="button" class="secondary" id="cancel-button">Cancel</button>
         <button type="button" class="danger" id="confirm-button">Delete image</button>
       </div>
     </div>
   </dialog>

   <script>
     const trigger = document.querySelector(".trigger");
     const dialog = document.getElementById("delete-dialog");
     const cancelButton = document.getElementById("cancel-button");
     const confirmButton = document.getElementById("confirm-button");
     const statusMessage = document.getElementById("status-message");

     let lastTrigger = null;

     function restoreFocus() {
       if (lastTrigger) {
         lastTrigger.focus();
       }
     }

     function closeDialog() {
       if (dialog.open) {
         dialog.close();
       }
     }

     trigger.addEventListener("click", (event) => {
       lastTrigger = event.currentTarget;
       dialog.showModal();
     });

     cancelButton.addEventListener("click", closeDialog);

     confirmButton.addEventListener("click", () => {
       statusMessage.textContent = "Image deleted from your library.";
       closeDialog();
     });

     dialog.addEventListener("close", restoreFocus);

